import{_ as s,o as r,c as a,a2 as n}from"./chunks/framework.BXzK3EA4.js";const k=JSON.parse('{"title":"常见排序算法详解","description":"排序是程序开发中非常常见的操作，对一组任意的数据元素经过排序操作后，就可以把他们变成一组一定规则排序的有序序列","frontmatter":{},"headers":[],"relativePath":"计算机基础/algorithms/14-sort.md","filePath":"计算机基础/algorithms/14-sort.md","lastUpdated":1793930980000}'),o={name:"计算机基础/algorithms/14-sort.md"};function i(d,t,l,e,h,g){return r(),a("div",null,[...t[0]||(t[0]=[n(`<h1 id="常见排序算法详解" tabindex="-1">常见排序算法详解 <a class="header-anchor" href="#常见排序算法详解" aria-label="Permalink to &quot;常见排序算法详解&quot;">​</a></h1><h2 id="一、是什么" tabindex="-1">一、是什么 <a class="header-anchor" href="#一、是什么" aria-label="Permalink to &quot;一、是什么&quot;">​</a></h2><p>排序是程序开发中非常常见的操作，对一组任意的数据元素经过排序操作后，就可以把他们变成一组一定规则排序的有序序列</p><p>排序算法属于算法中的一种，而且是覆盖范围极小的一种，彻底掌握排序算法对程序开发是有很大的帮助的</p><p>对与排序算法的好坏衡量，主要是从时间复杂度、空间复杂度、稳定性</p><p>时间复杂度、空间复杂度前面已经讲过，这里主要看看稳定性的定义</p><p>稳定性指的是假定在待排序的记录序列中，存在多个具有相同的关键字的记录，若经过排序，这些记录的相对次序保持不变</p><p>即在原序列中，r[i] = r[j]，且 r[i] 在 r[j] 之前，而在排序后的序列中，r[i] 仍在 r[j] 之前，则称这种排序算法是稳定的；否则称为不稳定的</p><h2 id="二、有哪些" tabindex="-1">二、有哪些 <a class="header-anchor" href="#二、有哪些" aria-label="Permalink to &quot;二、有哪些&quot;">​</a></h2><p>常见的<strong>比较类</strong>排序有 5 种。复杂度、稳定性与选型见文末的对比表,每个算法的完整实现与原理各有专篇:</p><table tabindex="0"><thead><tr><th>算法</th><th>一句话思路</th><th>专篇</th></tr></thead><tbody><tr><td><strong>冒泡排序</strong></td><td>反复比较相邻元素,顺序错就交换;每轮把当前最大值「冒」到末尾</td><td><a href="./5-bubbleSort">冒泡排序</a></td></tr><tr><td><strong>选择排序</strong></td><td>每轮从未排序部分挑出最小(或最大)放到已排序末尾</td><td><a href="./12-selectionSort">选择排序</a></td></tr><tr><td><strong>插入排序</strong></td><td>把元素插入到已排好序的子数组中的正确位置</td><td><a href="./9-insertionSort">插入排序</a></td></tr><tr><td><strong>归并排序</strong></td><td>分治:先使每个子序列有序,再把两个有序序列合并</td><td><a href="./10-mergeSort">归并排序</a></td></tr><tr><td><strong>快速排序</strong></td><td>选 pivot 做分区,小的放左大的放右,再对两部分递归</td><td><a href="./11-quickSort">快速排序</a></td></tr></tbody></table><p><strong>共同点</strong>:都是<strong>比较类</strong>排序——靠比较元素大小决定顺序,所以理论下界是 <strong>O(n log n)</strong>。</p><p><strong>非比较类</strong>(计数排序、桶排序、基数排序)可以突破这个下界,但前提是<strong>值域有特殊结构</strong>(比如分数只落在 0~100)。</p><h2 id="三、区别" tabindex="-1">三、区别 <a class="header-anchor" href="#三、区别" aria-label="Permalink to &quot;三、区别&quot;">​</a></h2><p>除了上述的排序算法之外，还存在其他的排序算法，例如希尔排序、堆排序等等......</p><p>区别如下图所示：</p><h2 id="🎯-面试常考" tabindex="-1">🎯 面试常考 <a class="header-anchor" href="#🎯-面试常考" aria-label="Permalink to &quot;🎯 面试常考&quot;">​</a></h2><h3 id="q1-常见排序算法的复杂度和适用场景" tabindex="-1">Q1：常见排序算法的复杂度和适用场景? <a class="header-anchor" href="#q1-常见排序算法的复杂度和适用场景" aria-label="Permalink to &quot;Q1：常见排序算法的复杂度和适用场景?&quot;">​</a></h3><p>见下方<strong>完整对比表</strong>。</p><p><strong>记忆锚点</strong>:</p><ul><li><strong>O(n log n) 且稳定</strong> → 归并</li><li><strong>O(n log n) 平均且原地</strong> → 快排</li><li><strong>O(n log n) 最坏 + O(1) 空间</strong> → 堆排</li><li><strong>O(n²) 但几乎有序时快</strong> → 插入排</li><li><strong>按 key 排序</strong> → 计数排 / 桶排</li></ul><p><strong>JS 的 <code>Array.prototype.sort</code> 用 TimSort</strong>:稳定、快速、对部分有序数组接近 O(n)。 所以 <code>sort((a,b) =&gt; a.x - b.x)</code> 是稳定的(ES2019 起规范强制)。</p><h3 id="q2-什么是稳定排序-为什么重要" tabindex="-1">Q2：什么是稳定排序?为什么重要? <a class="header-anchor" href="#q2-什么是稳定排序-为什么重要" aria-label="Permalink to &quot;Q2：什么是稳定排序?为什么重要?&quot;">​</a></h3><p><strong>稳定</strong>:相等元素排序后<strong>保持原有相对顺序</strong>。</p><p><strong>为什么重要</strong>:多关键字排序时可以<strong>分步进行</strong>—— 先按次要关键字排,再按主要关键字排(稳定),就等价于按多个关键字排序。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 先按分数排,再稳定地按姓名排 → 结果是「分数升序,同分按姓名升序」</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">people.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a.name.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">localeCompare</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(b.name))</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">people.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sort</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">((</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">a</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">b</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a.score </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b.score)</span></span></code></pre></div><p><strong>工程例子</strong>:表格多列排序、任务列表「优先级相同则按创建时间」、依赖注入排序。</p><p><strong>注意</strong>:JS 的 <code>sort</code> 在 ES2019 之前<strong>不保证稳定</strong>(V8 旧实现对 &gt;10 个元素用了不稳定排序), 这是老代码里偶发 bug 的来源。</p><h3 id="q3-计数排序和桶排序什么时候用" tabindex="-1">Q3：计数排序和桶排序什么时候用? <a class="header-anchor" href="#q3-计数排序和桶排序什么时候用" aria-label="Permalink to &quot;Q3：计数排序和桶排序什么时候用?&quot;">​</a></h3><p><strong>计数排序</strong>:值域<strong>已知且很小</strong>(如年龄 0-150、分数 0-100)。 用计数数组统计每个值出现次数,再按顺序写回,O(n + k)。</p><p><strong>桶排序</strong>:值可以<strong>均匀分布</strong>在一个区间里,分成若干桶,桶内排序后合并,期望 O(n)。</p><p><strong>共同点</strong>:都是<strong>非比较排序</strong>,突破 O(n log n) 的比较模型下界。</p><p><strong>前提很苛刻</strong>:</p><ul><li>值域太大就不适用(计数排序要 O(k) 空间)</li><li>分布不均匀就不适用(桶排序退化成 O(n²))</li></ul><p><strong>典型场景</strong>:统计类需求(年龄分布、分数段人数)、成绩排序。</p><h2 id="📝-小结" tabindex="-1">📝 小结 <a class="header-anchor" href="#📝-小结" aria-label="Permalink to &quot;📝 小结&quot;">​</a></h2><ul><li>排序选择看三个维度:时间复杂度、是否原地(空间)、是否稳定。</li><li>快速记忆:O(n log n) 稳定选归并,原地选快排,最好情况 O(n) 选插入排,值域小选计数排。</li><li>稳定性的价值在多关键字排序:分步排序即可实现「主键优先、同键按次键」。</li><li>JS 的 sort 是 TimSort(稳定),这在 ES2019 后是规范保证。</li></ul><h2 id="📊-常见排序算法对比" tabindex="-1">📊 常见排序算法对比 <a class="header-anchor" href="#📊-常见排序算法对比" aria-label="Permalink to &quot;📊 常见排序算法对比&quot;">​</a></h2><table tabindex="0"><thead><tr><th>算法</th><th>平均时间</th><th>最坏时间</th><th>空间</th><th>稳定</th><th>特点与适用</th></tr></thead><tbody><tr><td><strong>冒泡排序</strong></td><td>O(n²)</td><td>O(n²)</td><td>O(1)</td><td>✅</td><td>实现最简单;已有序时可提前退出到 O(n)</td></tr><tr><td><strong>插入排序</strong></td><td>O(n²)</td><td>O(n²)</td><td>O(1)</td><td>✅</td><td><strong>近有序时接近 O(n)</strong>;常作小数组优化</td></tr><tr><td><strong>选择排序</strong></td><td>O(n²)</td><td>O(n²)</td><td>O(1)</td><td>❌</td><td>交换次数仅 O(n),适合「比较便宜、交换昂贵」</td></tr><tr><td><strong>归并排序</strong></td><td>O(n log n)</td><td><strong>O(n log n)</strong></td><td><strong>O(n)</strong></td><td>✅</td><td>最好/最坏都一样;外部排序主力</td></tr><tr><td><strong>快速排序</strong></td><td>O(n log n)</td><td><strong>O(n²)</strong></td><td>O(log n)</td><td>❌</td><td>原地、缓存友好;需防 pivot 退化</td></tr><tr><td><strong>堆排序</strong></td><td>O(n log n)</td><td>O(n log n)</td><td>O(1)</td><td>❌</td><td>最坏也有 O(n log n) 且原地;Top K</td></tr><tr><td><strong>计数排序</strong></td><td>O(n + k)</td><td>O(n + k)</td><td>O(k)</td><td>✅</td><td><strong>非比较排序</strong>;值域 k 必须小</td></tr><tr><td><strong>桶排序</strong></td><td>O(n)</td><td>O(n²)</td><td>O(n + k)</td><td>✅</td><td>非比较排序;要求数据均匀分布</td></tr></tbody></table><blockquote><p>k 为值域大小。<strong>JavaScript 的 <code>Array.prototype.sort</code> 用的是 TimSort</strong> —— 稳定的混合排序, 对部分有序数组接近 O(n)。</p></blockquote><p><strong>选型速查</strong>:</p><ul><li>默认 → <code>Array.prototype.sort</code>(稳定、快、对部分有序友好)</li><li>要原地 + 内存紧 → 快排(记得三数取中选 pivot)</li><li>要稳定 + 数据在磁盘 → 归并</li><li>值域小(如分数 0~100)→ 计数排</li><li>Top K → 大小为 K 的堆,不要全排序</li></ul><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://www.runoob.com/w3cnote/bubble-sort.html" target="_blank" rel="noreferrer">https://www.runoob.com/w3cnote/bubble-sort.html</a></li><li><a href="http://www.x-lab.info/post/sort-algorithm/" target="_blank" rel="noreferrer">http://www.x-lab.info/post/sort-algorithm/</a></li><li><a href="https://zhuanlan.zhihu.com/p/42586566" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/42586566</a></li></ul>`,44)])])}const c=s(o,[["render",i]]);export{k as __pageData,c as default};
